                  where: "VS Code",
                  commands: "\"\"\"Fault injection for Lab 4. Off unless CHAOS_RATE is above 0.\"\"\"\nimport os\nimport random\n\nRATE = float(os.environ.get(\"CHAOS_RATE\", \"0\"))\n_rng = random.Random(0)\n\n\ndef reseed(seed) -> None:\n    \"\"\"Give each eval run its own repeatable fault sequence.\"\"\"\n    _rng.seed(str(seed))\n\n\ndef _fault(name, output):\n    kind = _rng.choice([\"timeout\", \"transient\", \"empty\", \"garbled\"])\n    if kind == \"timeout\":\n        raise TimeoutError(f\"{name} did not respond within 5 s\")\n    if kind == \"transient\":\n        raise ConnectionError(\"database is locked\")\n    if kind == \"empty\":\n        return '{\"columns\": [], \"rows\": []}' if name == \"run_sql\" else \"\"\n    return output[: max(1, len(output) // 3)]  # garbled: cut off mid-result\n\n\ndef wrap(name, fn):\n    def chaotic(**args):\n        output = fn(**args)\n        if RATE > 0 and _rng.random() < RATE:\n            return _fault(name, output)\n        return output\n    return chaotic\n\n\ndef wrap_all(functions: dict) -> dict:\n    # write_file is spared: a fault there would leave half-written files behind\n    return {n: (f if n == \"write_file\" else wrap(n, f)) for n, f in functions.items()}",
